"""Client protocol and response models for the Ratchet runtime.

All models use Pydantic with no hosted-service dependencies.
Pipeline output models (PendingSkillData, etc.) are defined here
to keep the client package self-contained and installable standalone.
"""

from __future__ import annotations

__all__ = [
    "ACTIVE_STATUSES",
    "ERROR_STATUSES",
    "TERMINAL_STATUSES",
    "ActivePipelineItem",
    "ActivePipelinesResult",
    "CausalStepFeedbackItem",
    "EnhanceSkillResult",
    "OperatorPlanItem",
    "OutputsResult",
    "PendingLessonData",
    "PendingSkillData",
    "PendingStrategyData",
    "PipelineConflictError",
    "PipelineStatusResult",
    "PipelineStopResult",
    "ProfileResult",
    "RatchetBaseClient",
    "ReliabilityMetrics",
    "SkillArtifactData",
    "SkillRefItem",
    "TriggerPipelineResult",
    "UploadResult",
    "UserProfile",
    "WisdomCurateResult",
    "WisdomFeedbackResult",
    "WisdomResultItem",
]

from pathlib import Path
from typing import Any, Literal, Protocol, runtime_checkable

from pydantic import BaseModel, ConfigDict, Field

from ratchet.client.models import TurnSet

# =============================================================================
# Pipeline Run Status Constants
# =============================================================================
# All valid statuses: queued → running → completed | failed | timeout | stopped
#
# These sets are the single source of truth for status classification.
# Use them instead of inline tuples to keep poll loops, queries, and
# branch logic consistent when new statuses are added.

TERMINAL_STATUSES: frozenset[str] = frozenset({"completed", "failed", "timeout", "stopped"})
"""Pipeline is done — poll loops should exit."""

ACTIVE_STATUSES: frozenset[str] = frozenset({"queued", "running"})
"""Pipeline is in progress — used for conflict checks and active-run queries."""

ERROR_STATUSES: frozenset[str] = frozenset({"failed", "timeout"})
"""Pipeline finished with an error — client should report the error field."""

# =============================================================================
# Pipeline Output Models (inlined from pipeline/store/base.py)
# =============================================================================


class PendingSkillData(BaseModel):
    """Data for a pending skill awaiting user review."""

    skill_name: str
    skill_md: str = Field(description="SKILL.md content")
    injection_rules: str = Field(description="JSON string of InjectionRules")
    evidence: str = Field(description="JSON string of evidence array")
    metadata: str = Field(description="JSON string of metadata dict")
    installed: bool = False
    approved: bool = False
    author: str = ""
    version: str = ""
    tags: list[str] = Field(default_factory=list)
    validation_level: str = Field(default="observed", description="Validation maturity for this skill")
    trust_tier: str = Field(default="provisional", description="Trust tier for this skill")
    safety_gate_status: str = Field(
        default="review_required",
        description="Whether the skill is approved to influence future sessions",
    )
    safety_gate_reason: str = Field(
        default="",
        description="Short explanation for the current safety gate status",
    )


class SkillArtifactData(BaseModel):
    """Data for a generated skill artifact (pipeline output)."""

    skill_id: str
    skill_type: str = ""
    decision: str = Field(description="PASS, MARGINAL, or FAIL")
    files: dict[str, str] = Field(default_factory=dict, description="filename -> content map")
    installed: bool = False
    approved: bool = False


class PendingStrategyData(BaseModel):
    """Data for a pending strategy awaiting user review."""

    strategy_name: str
    content: str = Field(description="Markdown content")
    category: str | None = None
    installed: bool = False
    approved: bool = False
    author: str = ""
    version: str = ""
    tags: list[str] = Field(default_factory=list)
    validation_level: str = Field(default="observed", description="Validation maturity for this strategy")
    trust_tier: str = Field(default="provisional", description="Trust tier for this strategy")
    safety_gate_status: str = Field(
        default="review_required",
        description="Whether the strategy is approved to influence future sessions",
    )
    safety_gate_reason: str = Field(
        default="",
        description="Short explanation for the current safety gate status",
    )


class PendingLessonData(BaseModel):
    """Data for a lesson document generated by the pipeline.

    Keep this shape stable; local runtime and UI code both read it.
    """

    slug: str
    title: str
    rendered_md: str = Field("", description="Rendered markdown content")
    run_id: str | None = None
    project_id: str | None = None
    author: str = ""
    version: str = ""
    tags: list[str] = Field(default_factory=list)


# =============================================================================
# Response Models
# =============================================================================


class UploadResult(BaseModel):
    """Result of storing trajectory data."""

    status: str = Field("accepted", description="Upload status")
    session_id: str = Field("", description="Session UUID")
    message: str = Field("", description="Human-readable message")


class OutputsResult(BaseModel):
    """Pipeline outputs for a project run."""

    skill_artifacts: list[SkillArtifactData] = Field(default_factory=list)
    pending_skills: list[PendingSkillData] = Field(default_factory=list)
    pending_strategies: list[PendingStrategyData] = Field(default_factory=list)
    pending_lessons: list[PendingLessonData] = Field(default_factory=list)


class TriggerPipelineResult(BaseModel):
    """Result of triggering a pipeline run."""

    run_id: str = Field(..., description="Unique pipeline run ID")
    status: str = Field("queued", description="Initial status")
    message: str = Field("", description="Human-readable message")


class PipelineConflictError(RuntimeError):
    """Raised when a local pipeline is already active for a project."""

    def __init__(self, *, project_id: str, run_id: str, detail: str | None = None) -> None:
        self.project_id = project_id
        self.run_id = run_id
        self.detail = detail or f"Pipeline already running for project {project_id}; run_id={run_id}"
        super().__init__(self.detail)


class PipelineStatusResult(BaseModel):
    """Status of a pipeline run."""

    run_id: str
    project_id: str
    status: str
    started_at: str | None = None
    completed_at: str | None = None
    progress: dict | None = None
    outputs: OutputsResult | None = None
    report: dict | None = None
    error: str | None = None
    run_dir: str | None = None
    log_path: str | None = None
    events_path: str | None = None
    last_heartbeat_at: str | None = None
    heartbeat_count: int = Field(default=0, ge=0)
    trace_id: str | None = None


class UserProfile(BaseModel):
    """User profile for personalization.

    Fields language/level/style are set via the CLI.
    """

    language: str | None = Field(None, description="Preferred language (e.g. English, Thai)")
    level: str | None = Field(None, description="Experience level (Beginner, Intermediate, Expert)")
    style: str | None = Field(None, description="Teaching style (Mentor, Formal, Concise)")

    model_config = ConfigDict(populate_by_name=True)


class ProfileResult(BaseModel):
    """Result of saving a profile."""

    success: bool = Field(True, description="Whether profile was saved")
    message: str = Field("", description="Human-readable message")


class EnhanceSkillResult(BaseModel):
    """Result of updating a skill with enhanced content."""

    success: bool = Field(True, description="Whether skill was enhanced")
    message: str = Field("", description="Human-readable message")


class PipelineStopResult(BaseModel):
    """Result of stopping a pipeline run."""

    run_id: str
    status: str
    message: str = ""


class ActivePipelineItem(BaseModel):
    """Summary of a single active pipeline run (client-side)."""

    run_id: str
    project_id: str
    status: str
    started_at: str | None = None
    progress: dict | None = None
    run_dir: str | None = None
    log_path: str | None = None
    events_path: str | None = None
    last_heartbeat_at: str | None = None
    heartbeat_count: int = Field(default=0, ge=0)
    trace_id: str | None = None


class ActivePipelinesResult(BaseModel):
    """List of active local pipeline runs."""

    active: bool = False
    runs: list[ActivePipelineItem] = Field(default_factory=list)


# =============================================================================
# Wisdom Curate (PCR Skill Networking)
# =============================================================================


class WisdomResultItem(BaseModel):
    """Single wisdom item from curate results."""

    wisdom_id: str = Field(description="Unique identifier of the wisdom record")
    score: float = Field(description="Relevance score from the wisdom graph")
    is_seed: bool = Field(default=False, description="Whether this wisdom is a seed node")
    predicted_success: float = Field(
        default=0.5,
        ge=0.0,
        le=1.0,
        description="Estimated probability that this wisdom will help on the current task",
    )
    confidence: float = Field(
        default=0.35,
        ge=0.0,
        le=1.0,
        description="Confidence in the predicted_success estimate for this wisdom",
    )
    should_abstain: bool = Field(
        default=False,
        description="Whether the system should avoid recommending this wisdom without more evidence",
    )
    abstain_reason: str = Field(
        default="",
        description="Short explanation for why the system would abstain on this wisdom",
    )
    validation_level: str = Field(
        default="observed",
        description="Validation maturity attached to the retrieved wisdom",
    )
    trust_tier: str = Field(
        default="provisional",
        description="Trust tier attached to the retrieved wisdom",
    )
    safety_gate_status: str = Field(
        default="review_required",
        description="Safety gate outcome for this wisdom item",
    )
    safety_gate_reason: str = Field(
        default="",
        description="Why this wisdom item received its safety gate status",
    )
    provenance: dict[str, Any] | None = Field(
        default=None,
        description="Validation, provenance, and revalidation metadata for this wisdom item",
    )


class ReliabilityMetrics(BaseModel):
    """Empirical reliability signals attached to a retrieved wisdom item."""

    selection_count: int = Field(default=0, ge=0, description="Number of reviewed selections for this operator")
    helped_count: int = Field(default=0, ge=0, description="Number of times the operator materially helped")
    hurt_count: int = Field(default=0, ge=0, description="Number of times the operator caused harm or confusion")
    unused_count: int = Field(default=0, ge=0, description="Number of times the operator was retrieved but not used")
    retrieval_miss_count: int = Field(
        default=0,
        ge=0,
        description="Number of feedback events that blamed retrieval for selecting or omitting this operator",
    )
    execution_miss_count: int = Field(
        default=0,
        ge=0,
        description="Number of feedback events that blamed execution after this operator was selected",
    )
    abstain_count: int = Field(
        default=0,
        ge=0,
        description="Number of times feedback indicated the system should have abstained",
    )
    prior_success: float = Field(
        default=0.5,
        ge=0.0,
        le=1.0,
        description="Evidence-based prior probability that this operator will help before current-task scoring",
    )
    confidence: float = Field(
        default=0.35,
        ge=0.0,
        le=1.0,
        description="Confidence in the prior_success estimate based on evidence volume and calibration",
    )
    retrieval_precision: float = Field(
        default=0.5,
        ge=0.0,
        le=1.0,
        description="Empirical rate at which retrieved instances of this operator were helpful",
    )
    execution_success_rate: float = Field(
        default=0.5,
        ge=0.0,
        le=1.0,
        description="Empirical success rate when this operator was executed or materially followed",
    )
    calibration_error: float = Field(
        default=0.25,
        ge=0.0,
        le=1.0,
        description="Mean absolute error between predicted and observed outcomes for this operator",
    )
    brier_score: float = Field(
        default=0.25,
        ge=0.0,
        le=1.0,
        description="Mean squared error between predicted and observed outcomes for this operator",
    )
    empirical_reliability: float = Field(
        default=0.0,
        ge=0.0,
        le=1.0,
        description="Evidence-weighted trust score derived from calibration and observed usefulness",
    )
    abstain_probability: float = Field(
        default=0.0,
        ge=0.0,
        le=1.0,
        description="Probability that the system should abstain from relying on this operator",
    )


class CausalStepFeedbackItem(BaseModel):
    """Structured per-step feedback for a curated operator."""

    operator_id: str = Field(default="", description="Operator identifier when known")
    title: str = Field(default="", description="Operator title when operator_id is unavailable")
    verdict: Literal["helped", "hurt", "unused", "missing"] = Field(
        default="helped",
        description="Whether the step helped, hurt, went unused, or was missing from retrieval",
    )
    failure_stage: Literal["none", "retrieval", "execution", "mixed", "unknown"] = Field(
        default="unknown",
        description="Where the miss occurred for this step",
    )
    note: str = Field(default="", description="Optional free-form note about this step")


class SkillRefItem(BaseModel):
    """Reference to a curated skill file."""

    name: str = Field(description="Skill name derived from the wisdom graph")
    path: str = Field(description="Relative path to the skill file within the ZIP")
    url: str = Field(default="", description="Legacy URL field; remote downloads are disabled")


class OperatorPlanItem(BaseModel):
    """Execution-assist plan item derived from the operator graph."""

    operator_id: str = Field(description="Unique identifier of the selected operator")
    title: str = Field(description="Human-readable operator title")
    source_artifact: str = Field(description="Source skill or artifact name")
    score: float = Field(description="Merged graph-aware relevance score")
    status: str = Field(description="Readiness status for execution assistance")
    is_seed: bool = Field(default=False, description="Whether the operator was selected during seed retrieval")
    wave: int = Field(default=0, ge=0, description="Topological execution wave index")
    parallelizable: bool = Field(default=False, description="Whether the operator can run in parallel with siblings")
    inclusion_reason: str = Field(default="", description="Short rationale for including the operator")
    context_package: list[str] = Field(
        default_factory=list,
        description="Minimal execution context package distilled for this operator",
    )
    depends_on: list[str] = Field(default_factory=list, description="Operator IDs that must run first")
    requires_context: list[str] = Field(
        default_factory=list, description="Operator IDs that establish required context"
    )
    conflicts_with: list[str] = Field(
        default_factory=list, description="Operator IDs that conflict with this operator"
    )
    missing_preconditions: list[str] = Field(
        default_factory=list, description="Preconditions not currently satisfied"
    )
    missing_slots: list[str] = Field(default_factory=list, description="Required slots lacking values")
    env_match_score: float = Field(
        default=0.0,
        ge=0.0,
        le=1.0,
        description="Environment fingerprint compatibility score",
    )
    predicted_success: float = Field(
        default=0.5,
        ge=0.0,
        le=1.0,
        description="Estimated probability that this operator will help on the current task",
    )
    confidence: float = Field(
        default=0.35,
        ge=0.0,
        le=1.0,
        description="Confidence in the predicted_success estimate",
    )
    should_abstain: bool = Field(
        default=False,
        description="Whether the system should abstain instead of strongly recommending this operator",
    )
    abstain_reason: str = Field(
        default="",
        description="Short rationale for abstaining on this operator",
    )
    reliability: ReliabilityMetrics | None = Field(
        default=None,
        description="Empirical reliability summary for this operator",
    )
    validation_level: str = Field(
        default="observed",
        description="Validation maturity attached to this operator",
    )
    trust_tier: str = Field(
        default="provisional",
        description="Trust tier attached to this operator",
    )
    safety_gate_status: str = Field(
        default="review_required",
        description="Safety gate outcome for this operator",
    )
    safety_gate_reason: str = Field(
        default="",
        description="Why this operator received its safety gate status",
    )
    provenance: dict[str, Any] | None = Field(
        default=None,
        description="Validation, provenance, and revalidation metadata for this operator",
    )


class WisdomCurateResult(BaseModel):
    """Result from local wisdom curation."""

    session_id: str = Field(description="Session identifier for linking feedback")
    query: str = Field(description="Original user query")
    curation: str = Field(description="Markdown curation document with step-by-step workflow")
    skills: list[SkillRefItem] = Field(default_factory=list, description="Curated skill references")
    wisdoms: list[WisdomResultItem] = Field(
        default_factory=list, description="Retrieved wisdom records with scores"
    )
    operator_plan: list[OperatorPlanItem] = Field(
        default_factory=list, description="Ordered operator plan for execution assistance"
    )
    readiness_summary: dict[str, int] | None = Field(
        default=None, description="Counts of operators grouped by readiness status"
    )
    confidence: float = Field(
        default=0.0,
        ge=0.0,
        le=1.0,
        description="Confidence in the top-level curation recommendation bundle",
    )
    should_abstain: bool = Field(
        default=False,
        description="Whether the system should abstain instead of giving a strong recommendation",
    )
    abstain_reason: str = Field(
        default="",
        description="Short rationale for abstaining on this curation",
    )
    token_count: int = Field(default=0, ge=0, description="Total LLM tokens consumed")
    cost_usd: float = Field(default=0.0, ge=0.0, description="Total LLM cost in USD")


class WisdomFeedbackResult(BaseModel):
    """Result from local wisdom feedback."""

    session_id: str = Field(description="Session identifier from the curate call")
    feedback_id: str = Field(description="Unique identifier for the submitted feedback")
    status: str = Field(default="saved", description="Feedback submission status")
    failure_stage: Literal["none", "retrieval", "execution", "mixed", "unknown"] = Field(
        default="unknown",
        description="Where the miss was attributed for this feedback event",
    )
    applied_steps: int = Field(
        default=0,
        ge=0,
        description="Number of operator-level causal feedback updates applied",
    )
    updated_operator_ids: list[str] = Field(
        default_factory=list,
        description="Operator IDs whose reliability metrics were updated",
    )


# Client Protocol
# =============================================================================


@runtime_checkable
class RatchetBaseClient(Protocol):
    """Client protocol for interacting with the Ratchet system.

    Implementations:
    - RatchetLocal: SQLite/filesystem-backed local runtime
    - RatchetRemote: deprecated compatibility shim delegating to RatchetLocal
    """

    def upload_trajectory(
        self,
        *,
        turn_set: TurnSet,
        project_id: str,
    ) -> UploadResult: ...

    def get_outputs(
        self,
        *,
        project_id: str,
        run_id: str,
    ) -> OutputsResult: ...

    async def trigger_pipeline_run(
        self,
        *,
        project_id: str,
        project_path: Path | None = None,
        session_id: str | None = None,
        steps: list[str] | None = None,
        force: bool = False,
        limit: int | None = None,
        concurrency: int = 64,
        model: str | None = None,
        include_claude: bool = False,
        include_codex: bool = False,
    ) -> TriggerPipelineResult: ...

    def get_pipeline_status(
        self,
        *,
        run_id: str,
    ) -> PipelineStatusResult: ...

    def save_profile(
        self,
        *,
        profile: UserProfile,
    ) -> ProfileResult: ...

    def load_profile(self) -> UserProfile: ...

    def stop_pipeline(self, *, run_id: str) -> PipelineStopResult: ...

    def get_active_pipelines(self) -> ActivePipelinesResult: ...

    def enhance_skill(
        self,
        *,
        skill_name: str,
        skill_md: str,
        version: str,
        metadata: dict | None = None,
    ) -> EnhanceSkillResult: ...

    def wisdom_curate(
        self,
        *,
        query: str,
        session_id: str = "",
        top_k: int = 20,
    ) -> WisdomCurateResult: ...

    def wisdom_feedback(
        self,
        *,
        session_id: str,
        feedback_text: str,
        failure_stage: Literal["none", "retrieval", "execution", "mixed", "unknown"] = "unknown",
        should_abstain: bool | None = None,
        step_feedback: list[CausalStepFeedbackItem] | None = None,
    ) -> WisdomFeedbackResult: ...
